// Count program for the Datadog MCP `execute_code`. Generated by `ws observe request`: the only
// line that changes is the one with the parameters. Read-only: counts only.
import { client, v2 } from "@datadog/datadog-api-client";

const P = /*ws:params*/null;

const REASON_CHARS = 120;

function buckets(response) {
  const data = response && response.data;
  if (Array.isArray(data)) return data;
  return (data && data.buckets) || [];
}

function bucketValue(bucket) {
  const attributes = bucket.attributes || {};
  const computes = bucket.computes || attributes.computes || attributes.compute || bucket.compute || {};
  const value = computes.c0;
  return value === undefined || value === null ? 0 : Number(value);
}

function totalOf(response) {
  if (response && response.meta && response.meta.status === "timeout") {
    throw new Error("partial result: timeout");
  }
  const first = buckets(response)[0];
  return first ? bucketValue(first) : 0;
}

function scalarSum(response) {
  if (response && response.errors) throw new Error("metric query failed");
  if (!response || !response.data || !response.data.attributes) throw new Error("unexpected response");
  const columns = response.data.attributes.columns || [];
  const column = columns.find((item) => item.type === "number");
  if (columns.length && !column) throw new Error("unexpected response");
  let sum = 0;
  for (const value of (column && column.values) || []) {
    if (typeof value === "number" && Number.isFinite(value)) sum += value;
  }
  return sum;
}

function counter(api, item) {
  const filter = { query: item.query, from: item.from, to: item.to };
  if (item.signal === "traces") {
    return async () => totalOf(await api.spans({ compute: [{ aggregation: "count", metric: "*" }], filter }));
  }
  if (item.signal === "logs") {
    return async () => totalOf(await api.logs({ compute: [{ aggregation: "count", type: "total" }], filter }));
  }
  if (item.signal === "metrics") {
    return async () =>
      scalarSum(
        await api.metrics({
          formulas: [{ formula: "a" }],
          queries: [{ dataSource: "metrics", name: "a", query: item.query, aggregator: "sum" }],
          from: Date.parse(item.from),
          to: Date.parse(item.to),
        }),
      );
  }
  return async () => {
    throw new Error("unknown signal");
  };
}

async function timed(job) {
  const started = new Date().toISOString();
  const value = await job();
  return { value, started, finished: new Date().toISOString() };
}

async function run(api) {
  const items = P.counts;
  const settled = await Promise.allSettled(items.map((item) => timed(counter(api, item))));
  const counts = [];
  const failed = [];
  items.forEach((item, i) => {
    const outcome = settled[i];
    if (outcome.status === "fulfilled") {
      counts.push({ check: item.check, hash: item.hash, ...outcome.value });
    } else {
      const error = outcome.reason;
      const reason = error && typeof error.code === "number" ? "HTTP " + error.code : String((error && error.message) || error);
      failed.push({ check: item.check, reason: reason.slice(0, REASON_CHARS) });
    }
  });
  return { version: 1, task: P.task, day: P.day, provider: "datadog", counts, failed };
}

// ws:entry
const configuration = client.createConfiguration();
const spansApi = new v2.SpansApi(configuration);
const logsApi = new v2.LogsApi(configuration);
const metricsApi = new v2.MetricsApi(configuration);
return await run({
  spans: (attributes) => spansApi.aggregateSpans({ body: { data: { type: "aggregate_request", attributes } } }),
  logs: (body) => logsApi.aggregateLogs({ body }),
  metrics: (attributes) =>
    metricsApi.queryScalarData({ body: { data: { type: "scalar_request", attributes } } }),
});
